begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('36000000-0000-4000-8000-000000000001','booking1@example.invalid'),('36000000-0000-4000-8000-000000000002','booking2@example.invalid'),('36000000-0000-4000-8000-000000000003','booking3@example.invalid');
insert into public.households(id,name) values ('36000000-0000-4000-8000-000000000100','Trip fixture'),('36000000-0000-4000-8000-000000000200','Other trip fixture');
insert into public.household_members(household_id,user_id,display_name) values ('36000000-0000-4000-8000-000000000100','36000000-0000-4000-8000-000000000001','Member 1'),('36000000-0000-4000-8000-000000000100','36000000-0000-4000-8000-000000000002','Member 2'),('36000000-0000-4000-8000-000000000200','36000000-0000-4000-8000-000000000003','Member 3');
select set_config('request.jwt.claim.sub','36000000-0000-4000-8000-000000000001',true);
set local role authenticated;
insert into public.household_projects(id,household_id,kind,title) values ('36000000-0000-4000-8000-000000000010','36000000-0000-4000-8000-000000000100','trip','Plan 10'),('36000000-0000-4000-8000-000000000011','36000000-0000-4000-8000-000000000100','project','Plan 11'),('36000000-0000-4000-8000-000000000012','36000000-0000-4000-8000-000000000100','trip','Plan 12');
select throws_ok($$insert into public.trip_bookings(id,household_id,project_id,kind,title) values ('36000000-0000-4000-8000-000000000021','36000000-0000-4000-8000-000000000100','36000000-0000-4000-8000-000000000011','flight','Flight')$$,'23514','Bookings require a trip','ordinary projects cannot receive bookings');
insert into public.trip_bookings(id,household_id,project_id,kind,title) values ('36000000-0000-4000-8000-000000000020','36000000-0000-4000-8000-000000000100','36000000-0000-4000-8000-000000000010','flight','Flight');
select throws_ok($$update public.trip_bookings set time_zone='not-a-zone' where id='36000000-0000-4000-8000-000000000020'$$,'23514','Bookings require valid named time zones','invalid zones cannot break itinerary rendering');
select set_config('test.booking.version',(select updated_at::text from public.trip_bookings where id='36000000-0000-4000-8000-000000000020'),true);
select set_config('request.jwt.claim.sub','36000000-0000-4000-8000-000000000002',true);
update public.trip_bookings set title='Partner flight' where id='36000000-0000-4000-8000-000000000020';
select is_empty($$update public.trip_bookings set title='Stale' where id='36000000-0000-4000-8000-000000000020' and updated_at=current_setting('test.booking.version')::timestamptz returning id$$,'stale booking edits cannot overwrite a partner');
select is((select title from public.trip_bookings where id='36000000-0000-4000-8000-000000000020'),'Partner flight','newest title is preserved');
select throws_ok($$update public.trip_bookings set project_id='36000000-0000-4000-8000-000000000012' where id='36000000-0000-4000-8000-000000000020'$$,'23514','A booking cannot change trips','booking parent identity is stable');
select throws_ok($$update public.household_projects set kind='project' where id='36000000-0000-4000-8000-000000000010'$$,'23514','A trip with bookings cannot become a project','parent cannot invalidate booking kind');
update public.household_projects set archived_at=now() where id='36000000-0000-4000-8000-000000000010';
select throws_ok($$insert into public.trip_bookings(id,household_id,project_id,kind,title) values ('36000000-0000-4000-8000-000000000022','36000000-0000-4000-8000-000000000100','36000000-0000-4000-8000-000000000010','flight','Flight')$$,'55000','Restore this trip before changing bookings','archived trips reject new bookings');
select throws_ok($$update public.trip_bookings set status='cancelled' where id='36000000-0000-4000-8000-000000000020'$$,'55000','Restore this trip before changing bookings','archived trips reject booking edits');
update public.household_projects set archived_at=null where id='36000000-0000-4000-8000-000000000010';
update public.trip_bookings set archived_at=now() where id='36000000-0000-4000-8000-000000000020';
select throws_ok($$update public.trip_bookings set title='Archived edit' where id='36000000-0000-4000-8000-000000000020'$$,'55000','Restore this booking before changing it','archived bookings must be restored');
select lives_ok($$update public.trip_bookings set archived_at=null where id='36000000-0000-4000-8000-000000000020'$$,'either member can restore a booking');
select set_config('request.jwt.claim.sub','36000000-0000-4000-8000-000000000003',true);
select is_empty($$select id from public.trip_bookings where id='36000000-0000-4000-8000-000000000020'$$,'foreign booking details are hidden');
select is_empty($$update public.trip_bookings set title='Foreign' where id='36000000-0000-4000-8000-000000000020' returning id$$,'foreign updates are denied');
select * from finish();
rollback;
